func randRoute(r *rand.Rand) string {
	segs := r.Intn(4) + 1
	s := ""
	for i := 0; i < segs; i++ {
		switch r.Intn(5) {
		case 0:
			s += "/a" + fmt.Sprint(r.Intn(3))
		case 1:
			s += "/:p" + fmt.Sprint(r.Intn(3))
		case 2:
			s += "/*"
