		case 3:
			s += "/b" + fmt.Sprint(r.Intn(3)) + "/c" + fmt.Sprint(r.Intn(2))
		case 4:
			s += "/:q" + fmt.Sprint(r.Intn(2)) + "/z"
		}
	}
	return s
}

func randPath(r *rand.Rand) string {
	chars := []string{"a", "b", "c", "z", "0", "1", "/", "/", ":", "*", "%", "x"}
	n := r.Intn(10)
	s := ""
	for i := 0; i < n; i++ {
		s += chars[r.Intn(len(chars))]
	}
	return s
}

func TestFuzzRouter3Tmp(t *testing.T) {
	r := rand.New(rand.NewSource(42))
	for iter := 0; iter < 20000; iter++ {
		n := r.Intn(6) + 1
		routes := []string{}
		seen := map[string]bool{}
		for i := 0; i < n; i++ {
			rt := randRoute(r)
			if !seen[rt] {
				seen[rt] = true
				routes = append(routes, rt)
			}
