func (c *context) Scheme() string {
	// Can't use `r.Request.URL.Scheme`
	// See: https://groups.google.com/forum/#!topic/golang-nuts/pMUkBlQBDF0
	if c.IsTLS() {
		return "https"
	}
	if scheme := c.request.Header.Get(HeaderXForwardedProto); isHTTPScheme(scheme) {
		return scheme
	}
	if scheme := c.request.Header.Get(HeaderXForwardedProtocol); isHTTPScheme(scheme) {
		return scheme
	}
	if ssl := c.request.Header.Get(HeaderXForwardedSsl); ssl == "on" {
		return "https"
	}
	if scheme := c.request.Header.Get(HeaderXUrlScheme); isHTTPScheme(scheme) {
		return scheme
	}
	return "http"
}

// isHTTPScheme reports whether the given value is a valid HTTP protocol scheme,
// i.e. `http` or `https`. Any other value (including an empty one) is invalid
// and must be ignored.
func isHTTPScheme(scheme string) bool {
	return scheme == "http" || scheme == "https"
}

