func (w *gzipResponseWriter) Write(b []byte) (int, error) {
	if len(b) == 0 {
		// Writing an empty slice would make the gzip writer emit its (10 byte)
		// header into the response while the body stays empty, leaving the client
		// with a body that cannot be decoded (the Content-Encoding header is
		// removed for empty responses). Nothing has to be written for an empty
		// body, so skip the underlying writer and content type sniffing.
		return 0, nil
	}
	if w.Header().Get(echo.HeaderContentType) == "" {
		w.Header().Set(echo.HeaderContentType, http.DetectContentType(b))
	}
	return w.Writer.Write(b)
}

