// Use implements `Echo#Use()` for sub-routes within the Group.
func (g *Group) Use(middleware ...MiddlewareFunc) {
	g.middleware = append(g.middleware, middleware...)
	if len(g.middleware) == 0 {
		return
	}
	// Allow all requests to reach the group as they might get dropped if router
	// doesn't find a match, making none of the group middleware process.
	// Do not overwrite routes that are already registered for the same path
	// (e.g. by another group sharing this group's path prefix), otherwise those
	// routes would be replaced by the not found handler.
	g.routeNotFound("", NotFoundHandler)
	g.routeNotFound("/*", NotFoundHandler)
}

// routeNotFound registers a catch-all route for the given path unless a route is
// already registered for that path.
func (g *Group) routeNotFound(path string, h HandlerFunc) {
	for _, m := range methods {
		if _, ok := g.echo.router.routes[m+g.prefix+path]; ok {
			continue
		}
		g.Add(m, path, h)
	}
}

